      flashcards: [
        { id: 'fc-38-1', front: 'Dominios 1.a) a 1.d)', back: 'a) $D = R^2$. b) $x^2+y^2 \\geq 4$. c) $x \\neq 0$. d) $x^2 - 2 \\neq y$.' },
        { id: 'fc-38-2', front: 'Dominio 1.g) — $\\frac{\\ln(x-y)}{\\sqrt{18-2x^2-2y^2}}$', back: '$D = \\{(x,y) \\in R^2 / x^2+y^2 < 9 \\wedge x < y\\}$. El $<$ es estricto porque la raíz está en el denominador.' },
        { id: 'fc-38-3', front: 'Dominio 1.h) — $\\frac{\\sqrt{9x^2+y^2-9}}{\\ln(y^2+x-1)}$', back: '$D = \\{(x,y) \\in R^2 / x^2 + \\frac{y^2}{9} \\geq 1 \\wedge y^2+x > 1 \\wedge y^2+x \\neq 2\\}$. Tres condiciones: radicando, argumento del log y log $\\neq 0$.' },
        { id: 'fc-38-4', front: 'Dominios 1.i) y 1.j)', back: 'i) $x^2 \\leq 1 \\wedge y^2 \\leq 1$ (un cuadrado). j) $x^2 + y^2 \\leq 36$ (círculo de radio 6, borde incluido).' },
        { id: 'fc-38-5', front: 'Ejercicio 2 — respuestas de la cátedra', back: 'a) $F(x,y) = \\frac{\\ln(x+y-1)}{\\sqrt{4-x^2-y^2}}$. b) $F(x,y) = \\frac{\\ln(y-x+1)}{\\sqrt{4-x^2-y}}$.' },
        { id: 'fc-38-6', front: 'Curvas de nivel de $F(x;y) = -x^2+2y$', back: '$z=1 \\rightarrow y = \\frac{1}{2}+\\frac{1}{2}x^2$; $z=-2 \\rightarrow y = -1+\\frac{1}{2}x^2$; $z=3 \\rightarrow y = \\frac{3}{2}+\\frac{1}{2}x^2$. Parábolas iguales desplazadas verticalmente.' },
        { id: 'fc-38-7', front: 'Curvas de nivel de $F(x;y) = xy$', back: '$z=1 \\rightarrow y = \\frac{1}{x}$; $z=-1 \\rightarrow y = -\\frac{1}{x}$; $z=0 \\rightarrow x=0 \\vee y=0$ (los dos ejes).' },
        { id: 'fc-38-8', front: 'Curvas de nivel de $F(x;y) = \\frac{x}{y^2+1}$', back: '$z=1 \\rightarrow x = 1+y^2$; $z=2 \\rightarrow x = 2+2y^2$; $z=0 \\rightarrow x = 0$. Parábolas de eje horizontal más el eje $y$.' },
        { id: 'fc-38-9', front: 'Curvas de nivel de $F(x;y) = x^2-y^2$', back: '$z=0 \\rightarrow |x|=|y|$ (dos rectas); $z=1 \\rightarrow x^2-y^2=1$; $z=-1 \\rightarrow y^2-x^2=1$ (hipérbola sobre el eje $y$).' },
        { id: 'fc-38-10', front: 'Curvas de nivel de $F(x;y) = \\ln(x-y)$', back: '$z=1 \\rightarrow y = x-e$; $z=0 \\rightarrow y = x-1$; $z=-1 \\rightarrow y = x-e^{-1}$. Rectas paralelas de pendiente $1$.' },
      ],
