            q: 'Según la resolución, ¿cuánto vale $f\'_x$ para $f(x;y) = 5x^{y-1}$?',
            options: ['$5(y-1) \\cdot x^{y-2}$', '$5x^{y-1} \\cdot \\ln x$', '$5x^{y-1}$', '$(y-1) \\cdot x^{y-1}$'],
            correctIndex: 0,
