              '$f(x;y) = 7xe^y \\Rightarrow f\'_y = 7xe^y$',
              '$f(x;y) = x^2y\\cos(xy) \\Rightarrow f\'_x = 2xy\\cos(xy) - x^2y^2\\operatorname{sen}(xy)$',
              '$f(x;y) = (2x^3+1)^{xy} \\Rightarrow f\'_y = x(2x^3+1)^{xy}\\ln(2x^3+1)$',
